import React from "react";
import '../style/Services.css';
import Card from 'react-bootstrap/Card';




const Services = () => {
  return (
    <main>
      <img className="img1" src="../images/banner.jpg" alt="fond violet avec un eclair blanc"></img>

      <div className="title2">
        <h1>Mon offre de services</h1>
        <h2>Voici les prestations sur lesquelles je peux intervenir</h2>
        <hr className="trait"></hr>
      </div>
      <Card style={{ width: '18rem' }}>
        <Card.Body>
          <img src="../images/brush.svg" alt="pinceau" style={{width:'20px'}}></img>
          <Card.Title>UX design</Card.Title>         
          <Card.Text>
            <p>L'UX Design est une discipline qui consiste à concevoir des produits
           (sites web, logiciels, applications mobiles, etc.)en plaçant l'utilisateur au centre des préoccupations.
           L'objectif est de rendre l'expérience utilisateur la plus fluidde et agréable possible.</p>
          </Card.Text>
         
        </Card.Body>
      </Card>

      <div className="presta">

      </div>
    </main>
  );


}

export default Services;
